The root cause is a single fault: ts-seat-service had a brief pod failure, and its two dependents (travel and travel2) then returned errors up the chain to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, metric, value FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'ts-seat-service%' AND metric = 'k8s.container.restarts' ORDER BY time LIMIT 20",
          "claim": "ts-seat-service container restart counter goes from 0 to 1 around 04:10:16 and stays there; one restart in the window."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS seat_server_spans FROM abnormal_traces WHERE service_name = 'ts-seat-service' AND attr_span_kind = 'Server' GROUP BY 1 ORDER BY 1",
          "claim": "ts-seat-service server spans stop for about 55 seconds (04:09:51 to 04:10:46) and then resume, matching the restart."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) AS n, min(time) AS first_seen, max(time) AS last_seen FROM abnormal_logs WHERE message LIKE '%ts-seat-service:8080%' AND message LIKE '%Connection refused%' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-travel2-service and ts-travel-service log 'Connection refused' on POST to ts-seat-service seats/left_tickets, all in the 04:10 minute."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n FROM abnormal_traces WHERE attr_span_kind = 'Client' AND attr_status_code = 'Error' AND service_name IN ('ts-travel2-service', 'ts-travel-service') GROUP BY ALL ORDER BY n DESC",
          "claim": "Outgoing client calls from ts-travel2-service and ts-travel-service fail with no HTTP status; these are the failed seat calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE c.attr_span_kind = 'Server' AND c.attr_status_code = 'Error' AND p.attr_span_kind = 'Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-travel2-service Server spans return 500 on /trips/left after its seat calls fail; the errors reach its callers."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name = 'ts-travel-service' GROUP BY ALL ORDER BY service_name, attr_span_kind",
          "claim": "ts-travel-service Server and Internal spans carry 35 errors in the abnormal window, and none in the normal window."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE c.service_name = 'ts-travel2-service' AND c.attr_span_kind = 'Server' AND c.attr_status_code = 'Error' AND p.service_name = 'ts-route-plan-service' GROUP BY ALL",
          "claim": "ts-route-plan-service client calls to ts-travel2-service return 500 and its own server spans then fail."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE c.service_name = 'ts-route-plan-service' AND c.attr_span_kind = 'Server' AND c.attr_status_code = 'Error' AND p.service_name = 'ts-travel-plan-service' GROUP BY ALL",
          "claim": "ts-travel-plan-service client calls to ts-route-plan-service return 500, so its own server spans fail too."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service', 'ts-ui-dashboard') AND attr_span_kind = 'Server' GROUP BY ALL ORDER BY service_name",
          "claim": "ts-travel-plan-service server spans fail with 500 (53 errors), and ts-ui-dashboard server spans return 500 to users (118 errors)."
        }
      ]
    }
  ]
}
